{"code": "export async function main(input: {}) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });

  const qualifying = issues.filter(i => i.status === "unresolved" && i.count >= 80);
  const culprits: string[] = [];
  for (const i of qualifying) if (!culprits.includes(i.culprit)) culprits.push(i.culprit);

  const toCreate: string[] = [];
  const alreadyCovered: { culprit: string; issue: string }[] = [];
  for (const c of culprits) {
    const found = await sdk.linear.searchIssues({ query: c });
    const hit = found.issues.find(i => i.title.includes(c) || i.description.includes(c));
    if (hit) alreadyCovered.push({ culprit: c, issue: hit.identifier });
    else toCreate.push(c);
  }

  const created = [];
  for (const c of toCreate) {
    const r = await sdk.linear.createIssue({ title: `[Sentry] ${c}`, description: c });
    created.push({ culprit: c, placeholder: r });
  }

  return {
    qualifyingSentryIssues: qualifying.map(i => ({ shortId: i.shortId, culprit: i.culprit, count: i.count })),
    distinctCulprits: culprits,
    alreadyCovered,
    creating: created.map(c => ({ title: `[Sentry] ${c.culprit}`, description: c.culprit })),
  };
}", "input": {}}

